'QZ_Step_Install' => '1. Instal QZ Tray di komputer ini — unduh gratis dari qz.io, lalu jalankan dan biarkan tetap berjalan (berada di system tray pada Windows atau menu bar pada macOS).',
'QZ_Step_Connect' => '2. Hubungkan printer label melalui USB dan pastikan sudah terpasang di sistem operasi (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. Klik tombol ⟳ di samping "Nama printer" di atas untuk mendeteksi printer di komputer ini, lalu pilih printer label Anda. Kosongkan kolom untuk memakai printer default komputer.',
'QZ_Step_Cert' => '4. Agar mencetak tanpa pop-up izin, unduh sertifikat di bawah dan salin ke folder instalasi QZ Tray dengan nama override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Lalu tutup QZ Tray dan jalankan kembali.',
'QZ_Step_Test' => '5. Klik "Cetak label uji" di bawah. Jika QZ Tray meminta izin, klik Allow — dengan sertifikat terpasang, izin tidak akan diminta lagi.',
