'QZ_Setup_Note' => 'QZ Tray berjalan di komputer tempat Anda membuka browser, sehingga tetap berfungsi meskipun Stocky di-host di server jarak jauh. Setiap komputer yang mencetak label harus memasang QZ Tray.',

