'Upd_Guide_Before_Title' => '1. Sebelum memperbarui',
'Upd_Guide_Before_Download' => 'Unduh {package} aplikasi dari akun CodeCanyon Anda ({path}). Jangan diekstrak — updater membutuhkan file ZIP persis seperti yang diunduh.',
'Upd_Latest_Full_Zip' => 'paket ZIP lengkap terbaru',
'Upd_Guide_Before_Admin' => 'Pastikan Anda masuk sebagai administrator yang memiliki izin {perm}. Tidak ada orang lain yang dapat melihat atau menjalankan updater.',
'Upd_Guide_Before_Quiet' => 'Pilih waktu yang sepi: selama pembaruan, aplikasi beralih ke mode pemeliharaan untuk sementara dan pengguna lain tidak dapat masuk.',
'Upd_Guide_Before_No_Manual' => 'Anda {not} perlu mencadangkan secara manual, mengekstrak file, menjalankan perintah, mengedit file konfigurasi, atau menyentuh database — updater melakukan semua itu secara otomatis. (Tentu saja, cadangan manual tambahan tidak ada salahnya.)',
'Upd_Not' => 'tidak',
'Upd_Guide_Code_Overwritten' => 'Jika Anda telah memodifikasi kode aplikasi secara manual, perubahan Anda akan ditimpa oleh pembaruan. Data, unggahan, pengaturan, dan .env Anda selalu dipertahankan.',
'Upd_Guide_Running_Title' => '2. Menjalankan pembaruan',
'Upd_Guide_Run_Open' => 'Buka {path} (halaman ini) dan tetap di tab {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: klik atau seret paket yang diunduh ke kotak unggah. File besar diunggah dalam potongan kecil, sehingga ini juga berfungsi di shared hosting dengan batas unggah rendah. Checksum melindungi dari unggahan yang rusak atau tidak lengkap.',
'Upd_Upload_The_Zip' => 'Unggah ZIP',
'Upd_Guide_Run_Validation' => '{auto} setelah unggahan (Anda dapat menjalankannya ulang dengan tombol {button}). Sistem memeriksa: integritas ZIP, struktur dan kelengkapan paket, kompatibilitas versi (penurunan versi ditolak), versi PHP dan ekstensi yang diperlukan, izin file, ruang disk kosong, koneksi database, konfigurasi, dan bahwa tidak ada pembaruan lain yang sedang berjalan.',
'Upd_Validation_Runs_Automatically' => 'Validasi berjalan secara otomatis',
'Upd_Guide_Run_Review' => 'Tinjau panel {panel}. Tombol {button} hanya muncul jika setiap pemeriksaan kritis lolos. Jika suatu pemeriksaan gagal, pesannya memberi tahu Anda dengan tepat apa yang harus diperbaiki.',
'Upd_Guide_Run_Click' => 'Klik {button} dan konfirmasi. Lalu cukup {keep} dan pantau jalur progres. Sistem menjalankan, secara berurutan:',
'Upd_Keep_Page_Open' => 'biarkan halaman ini tetap terbuka',
'Upd_Guide_Phase_Backup' => '{label} — dump database lengkap, ZIP dari setiap file aplikasi yang dapat diubah oleh pembaruan, dan salinan {env} dibuat lalu {verified}. Unggahan Anda ({images}) dan {storage} tidak pernah disentuh oleh pembaruan, sehingga tidak diarsipkan. Jika cadangan tidak dapat dibuat, pembaruan berhenti di sini dan tidak ada yang diubah.',
'Upd_Verified' => 'diverifikasi',
'Upd_Guide_Phase_Prepare' => '{label} — versi baru diekstrak ke area staging dan divalidasi lagi. Aplikasi yang sedang berjalan masih belum tersentuh.',
'Upd_Guide_Phase_Maintenance' => '{label} — mode pemeliharaan diaktifkan; pengunjung melihat layar ramah "Kami akan segera kembali".',
'Upd_Guide_Phase_Files' => '{label} — file baru dipasang hampir seketika; file lama disimpan terpisah untuk rollback. Jalur yang dilindungi ({env}, {storage}, {images}) tidak pernah diganti.',
'Upd_Guide_Phase_Database' => '{label} — migrasi dijalankan, lalu izin, terjemahan, dan templat diperbarui.',
'Upd_Guide_Phase_Cache' => '{label} — semua cache dibersihkan dan dibangun ulang.',
'Upd_Guide_Phase_Verify' => '{label} — pemeriksaan kesehatan memastikan versi baru dapat berjalan, database berfungsi, semua migrasi telah dijalankan, dan konfigurasi valid.',
'Upd_Guide_Phase_Done' => '{label} — mode pemeliharaan dinonaktifkan dan file sementara dibersihkan.',
'Upd_Guide_Run_Success' => 'Saat Anda melihat {success}, klik {reload} dan lakukan hard refresh pada browser Anda ({keys}) agar aset panel admin yang baru dimuat.',
'Upd_Update_Successful_Short' => 'Pembaruan berhasil',
'Upd_Guide_No_Internet' => 'Tidak diperlukan koneksi internet selama pembaruan — semuanya berasal dari ZIP yang diunggah. Kehilangan koneksi atau menutup browser TIDAK merusak pembaruan: server mengingat dengan tepat di mana proses berhenti.',
'Upd_Guide_Wrong_Title' => '3. Jika terjadi masalah',
'Upd_Guide_Wrong_Rollback' => '{label} — jika ada yang gagal setelah file mulai berubah (kesalahan ekstraksi, kegagalan migrasi, pemeriksaan kesehatan gagal, disk penuh, …), sistem secara otomatis memulihkan file sebelumnya dan database dari cadangan yang telah diverifikasi, menonaktifkan mode pemeliharaan, dan melaporkan {message}. Anda kembali tepat ke kondisi awal.',
'Upd_Automatic_Rollback' => 'Rollback otomatis',
'Upd_Failed_Previous_Restored' => 'Pembaruan gagal — versi sebelumnya dipulihkan',
'Upd_Guide_Wrong_Interrupted' => '{label} (server dimulai ulang, waktu habis, browser ditutup, listrik padam) — saat Anda membuka kembali halaman ini, banner merah menawarkan dua pilihan aman: {resume} (melanjutkan dari langkah tepat di mana proses berhenti) atau {rollback} (memulihkan versi sebelumnya dari cadangan).',
'Upd_Interrupted_Update' => 'Pembaruan terputus',
'Upd_Guide_Wrong_Unreachable' => '{label} — gunakan {console} mandiri di {path}. Konsol ini tetap berfungsi meskipun situs dalam mode pemeliharaan atau aset panel admin rusak, dan menawarkan tindakan Lanjutkan / Rollback yang sama. Ada juga tautan "Akses administrator" yang tidak mencolok di bagian bawah layar pemeliharaan.',
'Upd_Admin_Unreachable' => 'Panel admin tidak dapat dijangkau',
'Upd_Recovery_Console' => 'konsol pemulihan',
'Upd_Guide_Wrong_Locked_Out' => '{label} — selama pembaruan berjalan, halaman ini menampilkan {link}. Simpan tautan tersebut jika Anda perlu masuk kembali (misalnya setelah sesi Anda berakhir); tautan ini memungkinkan Anda melewati layar pemeliharaan agar dapat masuk lagi.',
'Upd_Locked_Out_Maintenance' => 'Terkunci oleh mode pemeliharaan',
'Upd_Bypass_Link' => 'tautan bypass',
'Upd_Guide_Wrong_Concurrent' => '{label} — mereka akan melihat {message} Hanya satu pembaruan yang dapat berjalan dalam satu waktu.',
'Upd_Another_Admin_Updating' => 'Admin lain mencoba memperbarui pada saat yang sama',
'Upd_Guide_Backups_Title' => '4. Cadangan & pemulihan',
'Upd_Guide_Backups_Created' => 'Setiap pembaruan membuat cadangan {before} menyentuh apa pun: semua file aplikasi yang dapat diganti oleh pembaruan, salinan {env}, dan dump database lengkap. Unggahan dan {storage} tidak pernah diubah oleh pembaruan sehingga tidak termasuk di dalamnya — simpan cadangan Anda sendiri untuk keduanya. Cadangan disimpan di {path} dan tidak pernah dapat diakses dari web.',
'Upd_Before' => 'sebelum',
'Upd_Guide_Backups_Panel' => 'Panel {panel} pada tab {tab} menampilkan daftarnya beserta tanggal, versi, dan ukuran. Dari sana Anda dapat {restore} cadangan lengkap mana pun (file + database — salinan pengaman database saat ini dibuat terlebih dahulu) atau {delete} cadangan lama.',
'Upd_Restore_Verb' => 'memulihkan',
'Upd_Delete_Verb' => 'menghapus',
'Upd_Guide_Backups_Retention' => 'Gunakan {keep} untuk memilih berapa banyak cadangan yang disimpan; cadangan yang lebih lama dihapus secara otomatis setelah setiap pembaruan berhasil. Satu-satunya cadangan lengkap yang tersisa tidak pernah dapat dihapus — Anda selalu memiliki jalan untuk kembali.',
'Upd_Guide_Manual_Title' => '5. Pembaruan manual (metode cadangan)',
'Upd_Guide_Manual_Text' => 'Jika Anda lebih suka memperbarui secara manual, atau pengunggah tidak dapat digunakan di server Anda, ikuti petunjuk langkah demi langkah pada tab {tab} di halaman ini.',
'Upd_Guide_Clear_Cache_First' => 'Jika halaman tampak rusak atau kosong setelah pembaruan apa pun, bersihkan cache browser Anda terlebih dahulu — itu hampir selalu penyebabnya.',
'Upd_Restore_Backup_Confirm' => 'Pulihkan cadangan ini? File dan database saat ini akan diganti dengan cadangan. Salinan pengaman database saat ini dibuat terlebih dahulu. (v{version} — {date})',
'Woo_Guide_Lead' => 'Cara toko WooCommerce tetap selaras dengan ERP. Baris cron di bawah dibuat khusus untuk server ini, sehingga dapat langsung disalin ke server.',
'Woo_Guide_Ways_Note' => 'Berbeda dengan Shopify, WooCommerce tidak mengirim apa pun ke ERP dengan sendirinya — tidak ada penerima webhook di sini, sehingga semua yang {in} datang sesuai jadwal. Hanya stok yang {out} yang dapat dikirim seketika.',
'Woo_In' => 'masuk',
'Woo_Out' => 'keluar',
'Woo_Guide_Both_Ways_Title' => 'Kedua cara memerlukan ini terlebih dahulu',
'Woo_Api_Keys' => 'Kunci API',
'Woo_Guide_Api_Keys_Text' => '{path}, izin {perm}. Salin consumer key dan secret ke tab {settings}, beserta URL toko — alamat situs Anda tanpa garis miring di akhir, mis. {example}.',
'Woo_Credentials_Saved' => 'kredensial tersimpan',
'Woo_Not_Configured_Yet' => 'belum dikonfigurasi',
'Woo_Guide_Wp_App_Password_Title' => 'Kata sandi aplikasi WordPress (opsional)',
'Woo_Guide_Wp_App_Password_Text' => 'Hanya digunakan untuk gambar produk. API WooCommerce memindahkan produk, stok, kategori, merek, pelanggan, dan pesanan; API WordPress-lah yang mencari di Media Library dan mengunggah gambar yang belum ada di sana.',
'Woo_Guide_Wp_App_Password_Note' => 'Gunakan pengguna WordPress yang dapat mengelola media, dan buat kata sandi di {path}. Biarkan kedua kolom kosong dan semuanya tetap tersinkronisasi — hanya lampiran gambar yang dilewati.',
'Woo_Guide_Pick_Way_Title' => 'Lalu pilih cara menjaganya tetap selaras',
'Woo_Right_Away' => 'Seketika',
'Woo_Stock_Live' => 'stok langsung',
'Woo_Stock_Not_Live' => 'stok tidak langsung',
'Woo_Guide_Realtime_Lead' => 'Hanya satu arah: stok dan produk yang keluar dari ERP. Pesanan dan perubahan produk yang dibuat di WooCommerce tetap datang sesuai jadwal — lihat tab lainnya.',
'Woo_Push_Stock_On_Change' => 'Kirim stok saat itu juga ketika berubah',
'Woo_Setting_People_Miss' => 'Inilah pengaturan yang sering terlewat',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Penjualan POS {not} mencapai WooCommerce dengan sendirinya. Jika dinonaktifkan, toko baru mengetahuinya pada sinkronisasi stok berikutnya — satu jam, secara default — dan dalam rentang waktu itu toko dapat menjual unit yang sudah Anda jual di kasir.',
'Woo_Does_Not' => 'tidak',
'Woo_Guide_Tick_Instant' => 'Centang {option} pada tab {settings}. Itulah seluruh pengaturannya — tanpa worker, tanpa cron. Setiap penjualan, retur, penyesuaian, transfer, dan pembelian yang diterima kemudian mengirim push hanya untuk produk tersebut, tepat setelah penjualan disimpan, dan penjualan dua puluh baris hanya memerlukan satu push, bukan dua puluh. Kasir tidak pernah menunggunya.',
'Woo_Currently' => 'Saat ini:',
'Woo_Instant_On_Text' => 'aktif — stok dikirim saat berubah',
'Woo_Instant_Off_Text' => 'nonaktif — stok hanya sesuai jadwal',
'Woo_Guide_Instant_Note' => 'Hanya produk yang sudah tertaut ke WooCommerce yang dikirim — produk yang belum pernah disinkronkan tidak memiliki apa pun di toko untuk dikoreksi. Produk variabel dikirim melalui induknya, dan produk kombo dikirim ulang ketika salah satu komponennya berubah. Operasi massal (menghapus produk, mengatur ulang gudang) menulis stok tanpa memicu event, yang menjadi salah satu alasan untuk tetap mempertahankan sinkronisasi stok per jam.',
'Woo_Push_Products_On_Save' => 'Kirim produk saat itu juga ketika disimpan',
'Woo_Guide_Tick_Auto_Products' => 'Centang {option} pada tab {settings} dan produk yang dibuat, diedit, atau diduplikasi di Stocky akan dikirim ke WooCommerce tepat setelah disimpan — detail, harga, varian, dan gambar, lalu stoknya. Produk baru langsung dibuat di toko tanpa menunggu sinkronisasi produk malam hari.',
'Woo_On' => 'aktif',
'Woo_Off' => 'nonaktif',
'Woo_Guide_Bulk_Imports_Note' => 'Impor massal tidak dikirim satu per satu — jalankan sinkronisasi produk setelah impor. Sinkronkan kategori dan merek terlebih dahulu, agar produk yang dikirim masuk ke kategori yang benar.',
'Woo_Nothing_Else_To_Install' => 'Tidak ada lagi yang perlu dipasang',
'Woo_Guide_Same_Process' => 'Tanpa queue worker, tanpa entri cron. Push berjalan dalam proses yang sama yang melayani penjualan, {after} respons dikirim kembali, sehingga kasir tidak pernah menunggu WooCommerce. Push tidak pernah tumpang tindih: perubahan yang dibuat saat satu push sedang berjalan akan menunggu dan dikirim tepat setelahnya.',
'Woo_After' => 'setelah',
'Woo_Guide_Shop_Stops_Answering' => 'Toko yang berhenti merespons akan ditinggalkan setelah delapan detik, dan push dijeda selama lima menit agar setiap penjualan tidak menunggunya lagi; perubahan yang masuk selama jeda dikirim bersama push pertama setelah jeda, dan sinkronisasi stok per jam tetap mengejar ketertinggalan. Setiap jeda dicatat di tab Log.',
'Woo_Guide_Artisan_Exception' => 'Satu pengecualian: perubahan stok yang dibuat oleh perintah artisan tidak memiliki respons untuk ditunggu, sehingga dimasukkan ke antrean {queue}. Agar perubahan tersebut juga segera terkirim, proses antrean itu:',
'Woo_Cron_Line_Copied' => 'Baris cron disalin',
'Woo_Command_Copied' => 'Perintah disalin',
'Woo_Guide_Not_Woo_Queue' => 'Sengaja tidak menggunakan antrean {queue}: antrean itu membawa batch katalog yang berlangsung berjam-jam, dan push instan yang mengantre di belakangnya tidak akan instan lagi.',
'Woo_On_A_Schedule' => 'Sesuai jadwal',
'Woo_Guide_Scheduled_Lead' => 'Semuanya diperiksa ulang secara berkala, ke dua arah. Inilah cara pesanan masuk ke ERP, cara katalog dipublikasikan, dan apa yang memperbaiki apa pun yang terlewat oleh jalur cepat. Setiap tugas memiliki entri cron sendiri, sehingga Anda hanya menjalankan yang Anda inginkan.',
'Woo_Guide_Sync_Drains_Queue' => '{command} memproses antreannya sendiri selama berjalan, sehingga baris-baris ini tidak memerlukan worker terpisah. Di Windows, gunakan Task Scheduler dengan program {program} dan argumen yang sama, dimulai di {path}.',
'Woo_Or_No_Cron' => 'Atau tanpa cron sama sekali',
'Woo_Guide_No_Cron_Text' => 'Setiap tab di sini dapat disinkronkan sesuai permintaan, dan sinkronisasi manual memproses batch-nya sendiri selama halaman terbuka — sehingga toko kecil dapat berjalan tanpa entri cron sama sekali. Yang hilang adalah semua yang terjadi saat tidak ada yang memantau: pesanan baru masuk ketika seseorang menekan tombol.',
'Woo_Commands_Worth_Knowing' => 'Perintah yang perlu diketahui',
'Woo_Worth_Knowing' => 'Perlu diketahui',
'Woo_Guide_Changing_Url_Clears' => 'Mengubah URL toko atau kunci API akan menghapus setiap pemetaan — produk, kategori, merek, dan pelanggan semuanya akan disinkronkan ulang ke toko baru.',
'Woo_Guide_Keep_Skus' => 'Jaga agar SKU konsisten antara Stocky dan WooCommerce: itulah yang mencegah duplikat dan membuat penautan ulang aman.',
