'Woo_Settings_Instant_Hint' => 'Penjualan, retur, atau penyesuaian mengirim push stok hanya untuk produk terkait saat itu juga ketika disimpan, sehingga toko sudah akurat dalam hitungan detik, bukan pada sinkronisasi stok per jam berikutnya. Tidak ada lagi yang perlu dipasang — push berjalan setelah penjualan dijawab, sehingga kasir tidak pernah menunggu WooCommerce. Selengkapnya di tab {guide}.',
