'Woo_Settings_Auto_Products_Hint' => 'Produk yang dibuat, diedit, atau diduplikasi di Stocky dikirim ke WooCommerce tepat setelah disimpan — detail, harga, varian, gambar, lalu stoknya — tanpa menunggu sinkronisasi produk. Impor massal tidak dikirim; jalankan sinkronisasi produk setelah impor.',
'Woo_Sync_Tuning' => 'Penyetelan sinkronisasi',
