'Woo_Setting_This_Up' => 'Menyiapkan ini',
'Woo_Setting_This_Up_Text' => 'Cara mendapatkan kunci API, kegunaan kata sandi aplikasi WordPress, entri cron untuk sinkronisasi terjadwal, dan cara membuat stok sampai ke toko saat itu juga ketika berubah — semuanya, dengan baris cron milik server ini yang siap disalin, ada di tab Panduan. Hanya satu salinan, sehingga tidak bisa menyimpang dari apa yang sebenarnya dilakukan modul.',
