'Telegram_G_B_Body' => 'Dua jenis pesan menunggu di antrean Telegram sendiri: pengiriman yang gagal (Telegram sementara tidak dapat dijangkau), yang dicoba ulang hingga tiga kali lagi dalam beberapa menit berikutnya; dan event yang muncul di luar admin — pesanan yang diimpor dari WooCommerce atau Shopify, perintah artisan. Entri cron ini mengirimkannya, dan tidak ada yang lain:',
