'Shopify_Hook_Note_Register' => 'Pendaftaran membuat langganan di Shopify dan mengarahkannya ke alamat ini secara otomatis. Jangan menambahkannya secara manual di Shopify → Settings → Notifications → Webhooks: webhook tersebut ditandatangani dengan secret yang berbeda dan setiap pengiriman akan ditolak.',
