'Shopify_Could_Not_Load_Store' => 'Tidak dapat memuat toko ini',
'Shopify_G_Lead_Store' => 'Apa yang dibutuhkan toko ini agar tetap selaras. Semua di sini khusus untuk toko ini — path dan ID-nya nyata, sehingga perintahnya dapat langsung disalin ke server.',
'Shopify_G_Lead_Generic' => 'Bagaimana toko Shopify tetap selaras dengan ERP. Pilih toko di atas untuk melihat statusnya sendiri, atau baca apa adanya — baris cron dan URL webhook sama untuk toko mana pun yang Anda hubungkan.',
'Shopify_G_Ways_Note' => 'Sebagian besar toko menjalankan keduanya: cara pertama menjaga toko tetap terkini dari menit ke menit, cara kedua menangkap apa pun yang terlewat oleh cara pertama — webhook yang tidak pernah tiba, perubahan yang dibuat langsung di admin Shopify, atau malam ketika situs sedang mati.',
'Shopify_G_Both_Need' => 'Kedua cara membutuhkan ini terlebih dahulu',
'Shopify_G_Credentials' => 'Kredensial Shopify',
'Shopify_G_Cred_Intro' => 'Sejak Januari 2026 Shopify tidak lagi membuat aplikasi kustom di dalam admin, sehingga ada dua jenis koneksi:',
'Shopify_G_Cred_DevDash' => '{app} (toko apa pun yang dihubungkan sekarang) — {path}. Berikan cakupan Admin API untuk apa yang disinkronkan toko ini, pasang aplikasi di toko, lalu salin {clientId} dan {clientSecret} dari halaman Settings aplikasi ke {where}. ERP menukarnya dengan token akses sendiri dan memperbaruinya sebelum kedaluwarsa setiap 24 jam. Client secret juga menandatangani webhook, sehingga tidak ada lagi yang diperlukan. Aplikasi dan toko harus berada di organisasi Shopify yang sama.',
'Shopify_G_Dev_Dashboard_App' => 'Aplikasi Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (dibuat di admin sebelum 2026) — tetap berfungsi tanpa perubahan dengan {token} ({prefix}) dan {secret} sebagai signing secret webhook. Nilainya tidak sama dengan token, dan tertukar keduanya adalah penyebab umum webhook ditolak.',
'Shopify_G_Legacy_App' => 'Aplikasi kustom lama',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'tersimpan',
'Shopify_G_Missing_Refused' => 'tidak ada — pengiriman akan ditolak',
'Shopify_G_Where_Data_Desc' => '{path} Gudang ERP yang stoknya dijual oleh toko ini, dan lokasi Shopify tempat stok tersebut ditulis. Sinkronisasi inventaris dan impor pesanan tidak akan berjalan tanpa keduanya.',
'Shopify_G_Currently' => 'Saat ini: gudang {warehouse}, lokasi {location}',
'Shopify_G_Not_Set_Lower' => 'belum diatur',
'Shopify_G_Ready' => 'siap',
'Shopify_G_Incomplete' => 'belum lengkap',
'Shopify_G_Manual_Syncs' => 'Sinkronisasi yang Anda mulai secara manual',
'Shopify_G_Manual_Desc' => 'Sinkronisasi yang dimulai dari {centre} langsung merespons dan berjalan di latar belakang, dalam potongan-potongan pendek yang masing-masing melanjutkan dari titik terakhir berhenti. Katalog besar tidak pernah terpotong di tengah jalan oleh hosting yang menghentikan permintaan web yang lama (LiteSpeed, nginx, load balancer), dan menutup halaman tidak menghentikannya. Worker untuk itu adalah satu baris cron lagi:',
'Shopify_G_Cron_Copied' => 'Baris cron disalin',
'Shopify_G_Manual_Note' => 'Tanpanya, sinkronisasi tetap selesai, tetapi hanya selama halaman Pusat Sinkronisasi tetap terbuka: jika tidak ada worker yang mengambil proses dalam beberapa detik, halaman akan melanjutkannya sendiri, satu permintaan pendek setiap kali. Di Windows gunakan Task Scheduler setiap menit: program {program}, argumen {args}, dimulai di {dir}.',
'Shopify_G_Then_Pick' => 'Lalu pilih cara menjaganya tetap selaras',
'Shopify_G_Right_Away' => 'Seketika',
'Shopify_G_Stock_Live' => 'stok langsung',
'Shopify_G_Stock_Not_Live' => 'stok tidak langsung',
'Shopify_G_Realtime_Lead' => 'Setiap perubahan dikirim saat terjadi, dalam hitungan detik. Ada dua bagian, dan keduanya merupakan sakelar terpisah: {webhooks} membawa masuk peristiwa dari toko, dan {push} mengirim stok keluar.',
'Shopify_G_Webhooks_Lower' => 'webhook',
'Shopify_G_Instant_Push_Lower' => 'pengiriman stok instan',
'Shopify_G_Webhooks_In' => 'Webhook — toko → ERP',
'Shopify_G_Webhooks_Desc' => 'Pesanan, perubahan status pesanan, serta perubahan produk, pelanggan, dan stok yang dibuat di Shopify. Buka toko dan tekan {button} di {tab} — aman ditekan dua kali. Shopify mengirim ke:',
'Shopify_G_Webhooks_Tab' => 'tab Webhook',
'Shopify_G_Webhooks_Note' => 'Alamat harus dapat dijangkau dari internet melalui HTTPS — Shopify tidak akan mengirim ke {localhost} atau domain {test}. Setiap pengiriman dicatat satu kali, sehingga percobaan ulang Shopify tidak dapat membuat pesanan duplikat, dan pengiriman yang gagal dapat diputar ulang. Pengiriman ditolak sampai signing secret dari langkah 1 disimpan.',
'Shopify_G_Instant_Out' => 'Pengiriman stok instan — ERP → toko',
'Shopify_G_Setting_Missed' => 'Inilah pengaturan yang sering terlewat',
'Shopify_G_Pos_Not_Auto' => 'Penjualan POS {not} sampai ke Shopify dengan sendirinya. Jika dimatikan, toko baru mengetahuinya pada langkah pengiriman Inventaris berikutnya — dan dalam jeda itu toko dapat menjual unit yang sudah Anda jual di kasir.',
'Shopify_G_Not' => 'tidak',
'Shopify_G_Tick_Push' => 'Centang {setting} di {where}. Hanya itu penyiapannya — tanpa worker, tanpa cron. Setiap penjualan, retur, dan penyesuaian kemudian mengirim pembaruan hanya untuk produk tersebut, tepat setelah penjualan disimpan, dan penjualan dua puluh baris hanya memerlukan satu pengiriman, bukan dua puluh. Kasir tidak pernah menunggunya.',
'Shopify_G_This_Store' => 'Toko ini:',
'Shopify_G_Push_On' => 'aktif — stok dikirim saat berubah',
'Shopify_G_Push_Off' => 'mati — stok hanya sesuai jadwal',
'Shopify_G_Push_Note' => 'Hanya produk yang sudah memiliki pemetaan Shopify, dan hanya pergerakan di gudang toko ini, yang dikirim. Operasi massal — menghapus produk, mengatur ulang gudang — menulis stok tanpa memicu peristiwa, yang menjadi salah satu alasan untuk tetap mempertahankan langkah inventaris terjadwal.',
'Shopify_G_Nothing_Install' => 'Tidak ada lagi yang perlu dipasang',
'Shopify_G_No_Worker_Note' => 'Kedua bagian tidak memerlukan queue worker maupun entri cron. Webhook yang masuk ditangani dalam permintaan yang dibuat Shopify; pengiriman stok keluar berjalan dalam proses yang sama yang melayani penjualan, {after} respons dikirim kembali — sehingga kasir tidak pernah menunggu Shopify, dan toko yang berhenti merespons akan ditinggalkan setelah sepuluh detik dan diserahkan ke pengiriman inventaris terjadwal berikutnya.',
'Shopify_G_After' => 'setelah',
'Shopify_G_Artisan_Note' => 'Satu pengecualian: perubahan stok yang dibuat oleh perintah artisan tidak memiliki respons untuk ditunggu, sehingga dimasukkan ke antrean {queue}. Jika Anda ingin perubahan tersebut juga segera dikirim, proses antrean itu:',
'Shopify_G_On_Schedule' => 'Sesuai jadwal',
'Shopify_G_On_Lower' => 'aktif',
'Shopify_G_Off_Lower' => 'mati',
'Shopify_G_Scheduled_Lead' => 'Semuanya diperiksa ulang secara berkala, ke dua arah. Lebih lambat dari real-time, tetapi inilah yang mengirim stok keluar pada toko yang tidak menggunakan pengiriman instan, menangkap webhook yang terlewat, dan satu-satunya cara untuk memindahkan seluruh katalog.',
'Shopify_G_Cron_Entry' => 'Entri cron',
'Shopify_G_Cron_Entry_Desc' => 'Tidak ada yang terjadwal berjalan tanpanya. Satu baris, khusus modul ini — tambahkan di samping apa pun yang telah Anda pilih untuk dijadwalkan:',
'Shopify_G_Cron_Note' => 'Setiap lima menit adalah resolusi terkecil yang dapat digunakan rencana, karena lima menit adalah interval langkah terpendek. Entri yang lebih jarang akan menjadi batas bawah — dengan {example}, langkah yang diatur 5 menit berjalan setiap 15 menit. Di Windows gunakan Task Scheduler: program {program}, argumen {args}, dimulai di {dir}.',
'Shopify_G_Switch_On_Plan' => 'Aktifkan, lalu pilih rencananya',
'Shopify_G_Plan_Desc' => '{where} Sakelar menentukan apakah cron boleh bertindak; rencana menentukan apa yang dilakukannya. Sebuah {step} adalah satu entitas dalam satu arah dengan intervalnya sendiri — {first}, {second}. Interval default digunakan oleh langkah mana pun yang kotak intervalnya dibiarkan kosong.',
'Shopify_G_Step_Lower' => 'langkah',
'Shopify_G_Plan_Note' => 'Biarkan rencana kosong dan toko akan menarik pesanan serta mengirim stok pada interval default, yang merupakan kebutuhan sebagian besar toko. Pesanan hanya ditarik: Shopify adalah tempat pelanggan membuat pesanan.',
'Shopify_G_Schedule_On' => 'jadwal aktif',
'Shopify_G_Schedule_Off' => 'jadwal mati — hanya manual',
'Shopify_G_When_Step_Runs' => 'Kapan sebuah langkah benar-benar berjalan',
'Shopify_G_When_Note' => 'Sebuah langkah jatuh tempo ketika langkah yang sama terakhir {started} lebih lama dari intervalnya, dibaca dari riwayat proses. Jadi sinkronisasi yang Anda mulai secara manual menunda sinkronisasi otomatis berikutnya, dan langkah yang terus gagal dicoba ulang sesuai intervalnya, bukan setiap tick. Ringkasan toko menampilkan proses terakhir setiap langkah, waktu jatuh tempo berikutnya, dan alasan pemblokirannya jika ada. Jalankan pengiriman katalog pertama secara manual — dengan {dryRun} terlebih dahulu — sebelum menjadwalkannya.',
'Shopify_G_Started_Lower' => 'dimulai',
'Shopify_G_Where_Setting' => 'Letak setiap pengaturan',
'Shopify_G_Where_Setting_Note' => 'Semua ini ada pada toko yang sudah ada: {path}, lalu ikon pensil (atau {edit} di halaman toko itu sendiri).',
'Shopify_G_Product_Images' => 'Gambar produk',
'Shopify_G_Img_1' => 'Gambar dikirim bersama produk pada {push} — gambar utama terlebih dahulu, lalu galeri, lalu satu untuk setiap varian yang memiliki gambar sendiri, hingga lima puluh.',
'Shopify_G_Products_Push' => 'pengiriman produk',
'Shopify_G_Img_2' => 'Gambar varian diunggah bersama produk lalu {assigned}, sesuai cara Shopify memodelkannya: varian merujuk ke salah satu gambar produk. Varian yang menggunakan gambar utama tidak mengunggahnya dua kali.',
'Shopify_G_Assigned' => 'ditetapkan ke varian tersebut',
'Shopify_G_Img_3' => 'Gambar yang disimpan sebagai file {uploaded} ke Shopify, bukan ditautkan, sehingga tetap berfungsi meskipun instalasi ini tidak dapat dijangkau dari internet. Gambar yang ditambahkan sebagai tautan yang ditempel diserahkan ke Shopify sebagai URL tersebut, yang harus dapat dijangkau publik.',
'Shopify_G_Uploaded' => 'diunggah',
'Shopify_G_Img_4' => 'Gambar hanya dikirim ulang jika benar-benar berubah — pengiriman yang hanya mengubah harga tidak menyentuh gambar toko, karena mengirimnya akan mengganti seluruh set.',
'Shopify_G_Img_5' => 'Menghapus gambar di ERP {not} menghapusnya di Shopify. Hapus juga di sana, atau toko akan tetap menampilkannya.',
