'Cr_Guide_T_Booking' => 'Memesan kurir',
'Cr_Guide_B_Booking' => 'Kirim ke kurir mengisi formulir dari penjualan: penerima, alamat, jumlah yang masih terutang sebagai COD, dan berat produk. Kurir yang memiliki daftar kota sendiri menampilkan pemilih, dan pilihan Anda diingat untuk kota tersebut. Agregator, DHL, FedEx, UPS, dan Lalamove menawarkan Bandingkan tarif: pilih harga, lalu Pesan akan membelinya. Beberapa penjualan dapat dipesan sekaligus dari daftar penjualan.',
'Cr_Guide_T_Cod' => 'Bayar di tempat (COD)',
'Cr_Guide_B_Cod' => 'Paket COD berpindah dari Belum ditagih ke Ditagih oleh kurir (saat diantar) ke Dicairkan ke Anda. Kurir yang melaporkan pencairan memindahkan langkah terakhir sendiri; untuk kurir lainnya gunakan Perbarui COD. Jika akun dipilih di Pengaturan Kurir, pencairan dicatat sebagai pembayaran pada penjualan. Biaya kurir dapat disimpan sebagai beban setelah paket selesai.',
'Cr_Guide_T_Returns' => 'Paket retur',
'Cr_Guide_B_Returns' => 'Secara default, paket retur menunggu di Pengiriman Kurir pada bagian Retur untuk ditinjau. Kembalikan ke stok membuat retur penjualan untuk seluruh pesanan dan mengembalikan barang ke stok; Abaikan tidak mengembalikan apa pun, untuk paket rusak atau hilang. Pengaturan Kurir dapat mengembalikan ke stok secara otomatis sebagai gantinya.',
'Cr_Guide_T_Customers' => 'Pesan pelanggan dan halaman pelacakan',
'Cr_Guide_B_Customers' => 'Notifikasi pelanggan di Pengaturan Kurir mengirim SMS, email, atau WhatsApp pada status yang Anda centang, masing-masing sekali per paket, dengan teks Anda sendiri. Halaman pelacakan di toko online Anda memungkinkan pelanggan melacak paket berdasarkan nomor resi, atau nomor pesanan dan telepon. Pelanggan yang sering meretur paket mendapat lencana risiko retur saat Anda memesan kurir.',
'Cr_Guide_T_Labels' => 'Label',
'Cr_Guide_B_Labels' => 'Cetak label memberikan label milik kurir jika kurir menerbitkannya (PDF, tautan, atau gambar), jika tidak, label Stocky dengan barcode pelacakan dan jumlah yang harus ditagih. Izinkan pop-up untuk situs ini agar dapat mencetak. DHL, FedEx, dan UPS hanya memberikan labelnya sekali, saat pemesanan, dan Stocky menyimpannya untuk dicetak ulang.',
'Cr_Guide_T_Faq' => 'Pemecahan masalah',
'Cr_Guide_Q_Test' => 'Uji koneksi gagal',
'Cr_Guide_A_Test' => 'Key mode uji dipakai dengan Mode uji dan key live dengan Live; keduanya berbeda. Buka Log kurir dan baca jawaban kurir untuk mengetahui alasan pastinya.',
'Cr_Guide_Q_City' => 'Kurir menolak kota atau alamat',
'Cr_Guide_A_City' => 'Pilih kota dari daftar kota kurir di formulir pemesanan; kurir hanya menerima nama versi mereka sendiri. Kurir yang menggunakan alamat pos juga memerlukan provinsi, kode pos, dan kode negara dua huruf.',
'Cr_Guide_Q_Webhook' => 'Status tidak berubah dengan sendirinya',
'Cr_Guide_A_Webhook' => 'Untuk kurir yang mengirim pembaruan, pastikan URL webhook terdaftar di kurir: Log kurir menampilkan setiap pembaruan yang diterima, atau alasan penolakannya (misalnya secret yang salah). Kurir lainnya diperiksa sesuai jadwal di Pengaturan Kurir, dan Cek status sekarang langsung menanyakannya.',
'Cr_Guide_Q_Stuck' => 'Pengiriman menampilkan kesalahan cek status',
'Cr_Guide_A_Stuck' => 'Kurir menolak pengecekan terakhir; alasannya ada di pengiriman dan di Log kurir. Setelah gagal berulang kali, pengiriman tidak lagi diperiksa secara otomatis: perbaiki penyebabnya, lalu gunakan Cek status sekarang.',
'Cr_Guide_Q_Label' => 'Tidak ada yang terbuka saat mencetak label',
'Cr_Guide_A_Label' => 'Browser Anda memblokir pop-up. Izinkan pop-up untuk situs ini dan coba lagi.',
'Cr_Guide_Q_Cod' => 'Pencairan COD tidak tercatat pada penjualan',
'Cr_Guide_A_Cod' => 'Di Pengaturan Kurir, bayar di tempat (COD) harus diaktifkan dan akun harus dipilih. Tanpa akun, pencairan hanya ditandai sebagai sudah dicairkan.',
