'Tfa_Guide_Enable_1' => 'Buka Profil (menu avatar di kanan atas) dan temukan kartu "Autentikasi dua faktor".',
'Tfa_Guide_Enable_2' => 'Klik "Aktifkan" dan konfirmasi dengan kata sandi saat ini.',
'Tfa_Guide_Enable_3' => 'Pindai kode QR dengan aplikasi, atau ketik key yang ditampilkan di bawahnya.',
'Tfa_Guide_Enable_4' => 'Masukkan kode 6 digit yang ditampilkan aplikasi untuk menyelesaikan.',
'Tfa_Guide_Open_Profile' => 'Buka profil saya',
'Tfa_Guide_Codes_Title' => 'Simpan kode pemulihan',
'Tfa_Guide_Codes_Text' => 'Tepat setelah penyiapan, 8 kode pemulihan ditampilkan satu kali. Setiap kode menggantikan kode ponsel satu kali — untuk ponsel yang hilang, rusak, atau direset. Unduh atau salin dan simpan di tempat yang aman, terpisah dari ponsel.',
'Tfa_Guide_Codes_Note' => 'Hampir habis? "Kode pemulihan baru" di profil mengganti seluruh set; kode lama tidak berlaku lagi.',
'Tfa_Guide_Signin_Title' => 'Masuk',
'Tfa_Guide_Signin_Text' => 'Setelah email dan kata sandi, halaman masuk meminta kode saat ini dari aplikasi. Kode berubah setiap 30 detik dan masing-masing hanya berlaku sekali.',
'Tfa_Guide_Signin_Trust' => 'Mencentang "Jangan tanya lagi di perangkat ini" melewati kode di browser tersebut selama :days hari.',
'Tfa_Guide_Signin_Recovery' => 'Tidak membawa ponsel? Klik "Gunakan kode pemulihan" dan ketik salah satu kode yang disimpan.',
'Tfa_Guide_Admin_Title' => 'Untuk administrator',
'Tfa_Guide_Require_Title' => 'Jadikan wajib',
'Tfa_Guide_Require_Text' => 'Aktifkan "Wajibkan autentikasi dua faktor" di kartu ini, lalu pilih peran yang harus menggunakannya — atau kosongkan daftar untuk semua pengguna. Klik Kirim untuk menyimpan.',
'Tfa_Guide_Require_Next' => 'Tidak ada yang dikeluarkan. Pengguna yang belum memiliki 2FA akan dipandu menyiapkannya di halaman masuk saat masuk berikutnya, sebelum mereka bisa masuk, dan melihat kode pemulihan mereka di sana.',
'Tfa_Guide_Require_Note' => 'Pengguna yang diwajibkan tidak dapat menonaktifkannya dari profil mereka.',
'Tfa_Guide_Trust_Title' => 'Perangkat tepercaya',
'Tfa_Guide_Trust_Text' => '"Ingat perangkat tepercaya" menentukan berapa lama sebuah browser dapat melewati kode setelah berhasil masuk. Pilih "Selalu minta kode" untuk komputer bersama atau publik seperti POS di lantai toko.',
'Tfa_Guide_Trust_Note' => 'Menurunkan angka ini memperpendek masa perangkat yang sudah tepercaya; menonaktifkan atau mereset 2FA akan melupakan semuanya.',
'Tfa_Guide_Lost_Title' => 'Ponsel hilang dan tidak ada kode pemulihan',
'Tfa_Guide_Lost_Text' => 'Di halaman Pengguna, pengguna dengan 2FA menampilkan "Aktif" di kolom 2FA. Tombol perisai di Aksi akan mereset-nya: pengguna masuk hanya dengan kata sandi dan menyiapkan aplikasi lagi (atau diminta melakukannya, jika diwajibkan).',
'Tfa_Guide_Lost_Warn' => 'Pastikan siapa yang meminta sebelum mereset — reset menghapus perlindungan yang diberikan 2FA pada akun tersebut.',
'Tfa_Guide_Open_Users' => 'Buka Pengguna',
'Tfa_Guide_Mobile_Title' => 'Aplikasi seluler dan API',
'Tfa_Guide_Mobile_Text' => 'Aplikasi seluler dan endpoint token API meminta kode yang sama. Jika 2FA diwajibkan untuk pengguna yang belum menyiapkannya, mereka harus masuk di web sekali untuk melakukannya.',
'Tfa_Guide_Protect_Title' => 'Perlindungan bawaan',
'Tfa_Guide_Protect_1' => '5 kode salah memblokir input kode untuk pengguna tersebut selama 15 menit, terlepas dari pengaturan penguncian di atas.',
'Tfa_Guide_Protect_2' => 'Setiap kode dan setiap kode pemulihan hanya berlaku sekali.',
'Tfa_Guide_Protect_3' => 'Jika "Catat aktivitas masuk" aktif, kode yang salah muncul di daftar Aktivitas masuk sebagai "Kode 2FA salah".',
'Tfa_Guide_Trouble_Title' => 'Pemecahan masalah',
'Tfa_Guide_Faq_Clock_Q' => '“Kode tersebut tidak valid” padahal kodenya baru',
'Tfa_Guide_Faq_Clock_A' => 'Jam ponsel kemungkinan tidak tepat. Kode bergantung pada waktu: atur tanggal dan waktu ponsel ke otomatis (waktu jaringan), lalu coba kode berikutnya.',
'Tfa_Guide_Faq_Phone_Q' => 'Pindah ke ponsel baru',
'Tfa_Guide_Faq_Phone_A' => 'Gunakan fitur transfer bawaan aplikasi autentikator, atau nonaktifkan 2FA di profil lalu aktifkan lagi dengan ponsel baru (jika diwajibkan, minta admin untuk mereset-nya).',
'Tfa_Guide_Faq_Locked_Q' => '“Terlalu banyak kode tidak valid”',
'Tfa_Guide_Faq_Locked_A' => 'Tunggu selama waktu yang ditampilkan (hingga 15 menit), atau minta admin mereset 2FA pengguna tersebut.',
'Tfa_Guide_Faq_Key_Q' => 'Tidak ada pengguna dengan 2FA yang bisa masuk setelah pindah server',
'Tfa_Guide_Faq_Key_A' => 'Secret 2FA dienkripsi dengan APP_KEY di file .env. Pertahankan APP_KEY yang sama saat memindahkan atau memulihkan aplikasi; jika berubah, admin tanpa 2FA harus mereset pengguna yang terdampak.',
