'Tfa_Guide_Rollout_Title' => 'Terapkan ke semua pengguna',
'Tfa_Guide_Rollout_1' => 'Aktifkan untuk akun Anda sendiri terlebih dahulu (Profil), agar Anda memahami langkah-langkahnya.',
'Tfa_Guide_Rollout_2' => 'Beri tahu tim Anda aplikasi mana yang harus dipasang dan bahwa penyiapan hanya butuh satu menit saat masuk.',
'Tfa_Guide_Rollout_3' => 'Aktifkan "Wajibkan autentikasi dua faktor", kosongkan "Wajib untuk" (= semua pengguna), dan secara opsional pilih masa tenggang. Klik Kirim.',
'Tfa_Guide_Rollout_4' => 'Klik "Keluarkan pengguna tanpa 2FA" agar orang yang sudah masuk menyiapkannya sekarang, bukan saat masuk berikutnya. Anda tetap masuk.',
'Tfa_Guide_Rollout_5' => 'Pantau perkembangan dengan penghitung di kartu ini, atau filter "Perlu disiapkan" di halaman Pengguna.',
'Tfa_Guide_Rollout_Note' => 'Dengan masa tenggang, layar penyiapan menampilkan “Ingatkan saya nanti” hingga batas waktu; setelah itu, penyiapan wajib untuk masuk.',
'Tfa_Guide_Customers_Title' => 'Akun pelanggan (toko dan portal klien)',
'Tfa_Guide_Customers_Text' => 'Pelanggan juga dapat melindungi akun mereka sendiri. Fitur ini opsional untuk setiap pelanggan dan tidak pernah dipaksakan: aktifkan di Pengaturan Toko → Kontrol Akses Pendaftaran (toko online) dan Portal Klien → Pengaturan Portal (portal klien).',
'Tfa_Guide_Customers_1' => 'Pelanggan mengaktifkannya dari Akun Saya (toko) atau Profil (portal).',
'Tfa_Guide_Customers_2' => 'Mereka memilih kode yang dikirim melalui email — paling mudah, tanpa aplikasi — atau aplikasi autentikator dengan kode pemulihan.',
'Tfa_Guide_Customers_3' => 'Kode via email memerlukan pengaturan email yang berfungsi (Pengaturan → Pengaturan Email). Kode kedaluwarsa setelah 10 menit.',
'Tfa_Guide_Customers_4' => 'Menonaktifkan opsi ini nanti akan menghentikan penyiapan baru; pelanggan yang sudah menggunakannya tetap akan diminta kode dan dapat menonaktifkannya sendiri.',
